<!doctype html><html><head><meta charset="utf-8"><title>{{ $premium->receipt_no }}</title><style>body{font-family:Arial,sans-serif;font-size:13px}.box{border:1px solid #333;padding:15px}.title{text-align:center}</style></head><body onload="window.print()"><div class="box"><h2 class="title">Insurance Premium Receipt</h2><p><b>Receipt No:</b> {{ $premium->receipt_no }}</p><p><b>Policy No:</b> {{ optional($premium->policy)->policy_no }}</p><p><b>Customer:</b> {{ optional($premium->policy)->customer_name }}</p><p><b>Date:</b> {{ optional($premium->payment_date)->format('Y-m-d') }}</p><p><b>Amount:</b> {{ number_format($premium->amount,4) }}</p><p><b>Method:</b> {{ $premium->payment_method }}</p></div></body></html>
